1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	
4	const BASE_PREMIUM: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	};
11	
12	type Item = { type: string };
13	type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Array<{ op: "quote"; items: Item[] }>;
16	};
17	
18	const itemPremium = (item: Item): number =>
19	  BASE_PREMIUM[item.type] * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
20	
21	const roundUpInFavorOfInsurer = (amount: number): number =>
22	  Math.ceil(Math.round(amount * 1e6) / 1e6);
23	
24	const quotePremium = (items: Item[]): number => {
25	  const itemsTotal = items.reduce((sum, item) => sum + itemPremium(item), 0);
26	  return roundUpInFavorOfInsurer(itemsTotal + PROCESSING_FEE);
27	};
28	
29	export const runScenario = (scenario: unknown): unknown => ({
30	  results: (scenario as Scenario).steps.map((step) => ({
31	    premium: quotePremium(step.items),
32	  })),
33	});
